import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.XXezeKOl.js";const h=JSON.parse('{"title":"架构师路径","description":"面向已有大模型应用经验、负责技术选型和系统设计的工程师，约 6 周，聚焦架构决策、评估体系与生产治理。","frontmatter":{"title":"架构师路径","description":"面向已有大模型应用经验、负责技术选型和系统设计的工程师，约 6 周，聚焦架构决策、评估体系与生产治理。"},"headers":[],"relativePath":"roadmap/architect.md","filePath":"roadmap/architect.md","lastUpdated":null}'),l={name:"roadmap/architect.md"};function n(o,e,g,p,s,d){return i(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="架构师路径" tabindex="-1">架构师路径 <a class="header-anchor" href="#架构师路径" aria-label="Permalink to &quot;架构师路径&quot;">​</a></h1><p>这条路径适合已经做过大模型应用、需要为团队做技术选型和系统设计的人。默认你已经能熟练使用 Tool Calling 和 RAG，所以前两个阶段只做快速校准，时间主要花在上下文工程、多 Agent 架构、评估体系和生产治理上。</p><p>节奏按每周 6 到 8 小时估算，约 6 周。每个阶段除了读文章，都要求产出一份设计文档或决策记录，这比代码更能检验架构能力。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 周              第 2 周            第 3 周               第 4 周              第 5-6 周</span></span>
<span class="line"><span>基础与模型校准 ──▶  Agent 循环设计 ──▶ 上下文与知识架构 ──▶ 多 Agent 与生态 ──▶  评估、安全与生产治理</span></span>
<span class="line"><span>（阶段 1+2）        （阶段 3）         （阶段 4）            （阶段 4、5）         （阶段 5）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="阶段-1-2-基础与模型校准-第-1-周" tabindex="-1">阶段 1 + 2：基础与模型校准（第 1 周） <a class="header-anchor" href="#阶段-1-2-基础与模型校准-第-1-周" aria-label="Permalink to &quot;阶段 1 + 2：基础与模型校准（第 1 周）&quot;">​</a></h2><p>目标：统一团队对 Agent 的定义，建立模型选型方法。</p><p>必读：</p><ul><li><a href="/guide/00-intro/agent-vs-workflow">Agent、Chatbot 与 Workflow 的区别</a></li><li><a href="/guide/00-intro/capabilities">Agent 的能力边界与适用场景</a></li><li><a href="/guide/02-llm-basics/reasoning-models">推理模型与扩展思考</a></li><li><a href="/guide/02-llm-basics/choosing-models">如何选择模型</a></li><li><a href="/guide/03-llm-api/providers">主流模型厂商 API 对比</a></li><li><a href="/guide/04-prompt/prompt-management">提示词版本管理与测试</a></li></ul><p>可以跳过：模块 01 全部，模块 02 到 04 中的入门文章。</p><p>产出：一份《模型选型方法》文档，说明你们团队如何按任务难度、延迟、成本、数据合规在多个模型之间选择，以及如何避免被单一厂商锁定。</p><p>自检清单：</p><ul><li>[ ] 能向业务方解释哪些需求适合 Agent，哪些用固定 Workflow 更好</li><li>[ ] 有一套可复用的模型对比方法，而不是凭感觉选模型</li><li>[ ] 提示词和模型版本可追溯，变更有评估结果支撑</li></ul><h2 id="阶段-3-agent-循环设计-第-2-周" tabindex="-1">阶段 3：Agent 循环设计（第 2 周） <a class="header-anchor" href="#阶段-3-agent-循环设计-第-2-周" aria-label="Permalink to &quot;阶段 3：Agent 循环设计（第 2 周）&quot;">​</a></h2><p>目标：能为不同任务选择合适的控制流，并设计可控的工具体系。</p><p>必读：</p><ul><li><a href="/guide/05-tool-calling/tool-design">工具设计原则</a></li><li><a href="/guide/05-tool-calling/error-handling">工具错误处理与重试</a></li><li><a href="/guide/06-agent-loop/plan-execute">Plan-and-Execute</a></li><li><a href="/guide/06-agent-loop/reflection">Reflection 自我反思</a></li><li><a href="/guide/06-agent-loop/stop-budget">终止条件、步数与预算控制</a></li><li>论文：<a href="/papers/react">ReAct</a>、<a href="/papers/reflexion">Reflexion</a>、<a href="/papers/tree-of-thoughts">Tree of Thoughts</a></li></ul><p>可以略读：<a href="/guide/05-tool-calling/concept">工具调用原理</a>、<a href="/guide/06-agent-loop/handwritten-agent">不用框架手写 Agent</a>。如果团队里还没人手写过 Agent 循环，建议你亲自做一遍 <a href="/projects/03-react-agent">03 手写 ReAct Agent</a>。</p><p>产出：一份《工具规范》，包括工具命名、描述、参数设计、错误返回格式、幂等性要求、读写权限分级。</p><p>自检清单：</p><ul><li>[ ] 能针对一个具体业务说明为什么选 ReAct、Plan-and-Execute 或固定 Workflow</li><li>[ ] 工具粒度有统一标准，避免&quot;一个工具做所有事&quot;或&quot;工具多到模型选不对&quot;</li><li>[ ] 每个 Agent 都有步数、Token、时间和金额四类预算上限</li></ul><h2 id="阶段-4-上下文与知识架构-第-3-周" tabindex="-1">阶段 4：上下文与知识架构（第 3 周） <a class="header-anchor" href="#阶段-4-上下文与知识架构-第-3-周" aria-label="Permalink to &quot;阶段 4：上下文与知识架构（第 3 周）&quot;">​</a></h2><p>目标：设计上下文组装、记忆和知识检索的整体方案。</p><p>必读：</p><ul><li><a href="/guide/07-context-engineering/overview">什么是上下文工程</a>、<a href="/guide/07-context-engineering/window-management">上下文窗口管理</a>、<a href="/guide/07-context-engineering/compression">压缩与摘要</a>、<a href="/guide/07-context-engineering/prompt-caching">Prompt Caching</a></li><li><a href="/guide/08-memory/long-term">长期记忆与用户画像</a>、<a href="/guide/08-memory/memory-strategy">记忆读写策略与方案对比</a></li><li><a href="/guide/09-rag/hybrid-rerank">混合检索与重排</a>、<a href="/guide/09-rag/advanced-rag">GraphRAG 与 Agentic RAG</a>、<a href="/guide/09-rag/rag-eval">RAG 评估</a></li><li>论文：<a href="/papers/rag">RAG 原始论文</a>、<a href="/papers/generative-agents">Generative Agents</a></li></ul><p>可以略读：<a href="/guide/09-rag/overview">RAG 全景</a>、<a href="/guide/09-rag/chunking">文档解析与切分</a>、<a href="/guide/09-rag/vector-db">向量数据库</a>。</p><p>产出：一份上下文架构图，标出系统提示词、工具定义、记忆、检索结果、对话历史各自的来源、预算占比和缓存策略。</p><p>自检清单：</p><ul><li>[ ] 上下文的组装顺序考虑了 Prompt Caching 命中率</li><li>[ ] 能说明长期记忆的写入时机、冲突处理和删除机制（含用户隐私要求）</li><li>[ ] 能判断什么情况下 GraphRAG 或 Agentic RAG 值得引入</li><li>[ ] 知识库的权限能做到文档级别隔离</li></ul><h2 id="阶段-4-5-多-agent-与生态-第-4-周" tabindex="-1">阶段 4 + 5：多 Agent 与生态（第 4 周） <a class="header-anchor" href="#阶段-4-5-多-agent-与生态-第-4-周" aria-label="Permalink to &quot;阶段 4 + 5：多 Agent 与生态（第 4 周）&quot;">​</a></h2><p>目标：在框架、协议和多 Agent 架构之间做出有依据的选择。</p><p>必读：</p><ul><li><a href="/guide/10-mcp/mcp-overview">MCP 架构与核心概念</a>、<a href="/guide/10-mcp/mcp-client">在应用中接入 MCP</a>、<a href="/guide/10-mcp/a2a">A2A：Agent 之间的协议</a></li><li><a href="/guide/11-frameworks/overview">框架全景与选型</a>、<a href="/guide/11-frameworks/langgraph">LangGraph</a>、<a href="/guide/11-frameworks/agent-sdks">Claude Agent SDK 与 OpenAI Agents SDK</a></li><li><a href="/guide/12-multi-agent/why-multi-agent">为什么需要多 Agent</a>、<a href="/guide/12-multi-agent/patterns">编排模式</a>、<a href="/guide/12-multi-agent/state-sharing">状态共享与通信</a>、<a href="/guide/12-multi-agent/pitfalls">多 Agent 的坑与成本控制</a></li><li><a href="/guide/13-coding-agent/coding-agents">Coding Agent 原理</a>、<a href="/guide/13-coding-agent/sandbox">沙箱与代码执行安全</a></li><li>论文：<a href="/papers/swe-agent">SWE-agent</a></li></ul><p>项目：<a href="/projects/07-writing-team">07 多 Agent 写作团队</a>，重点对比单 Agent 和多 Agent 版本在质量、成本、延迟上的差异。</p><p>产出：一份《框架与协议选型 ADR》（架构决策记录），说明是否使用框架、用哪个、内部工具是否统一以 MCP 暴露。</p><p>自检清单：</p><ul><li>[ ] 能说出至少三种多 Agent 编排模式及适用场景</li><li>[ ] 能量化多 Agent 带来的额外 Token 成本</li><li>[ ] 对 MCP Server 的来源、权限和审计有明确策略</li><li>[ ] 执行代码或操作系统的 Agent 一定运行在隔离环境中</li></ul><h2 id="阶段-5-评估、安全与生产治理-第-5-6-周" tabindex="-1">阶段 5：评估、安全与生产治理（第 5-6 周） <a class="header-anchor" href="#阶段-5-评估、安全与生产治理-第-5-6-周" aria-label="Permalink to &quot;阶段 5：评估、安全与生产治理（第 5-6 周）&quot;">​</a></h2><p>目标：建立团队级的评估体系和上线标准。</p><p>必读：</p><ul><li>模块 14 全部：<a href="/guide/14-evaluation/why-evals">为什么评估是第一优先级</a>、<a href="/guide/14-evaluation/eval-design">评估集与指标设计</a>、<a href="/guide/14-evaluation/llm-judge">LLM-as-Judge</a>、<a href="/guide/14-evaluation/observability">轨迹追踪与可观测性</a>、<a href="/guide/14-evaluation/regression">回归测试与持续评估</a></li><li>模块 15 全部：<a href="/guide/15-production/prompt-injection">Prompt 注入与防护</a>、<a href="/guide/15-production/permissions-hitl">权限控制与人在环路</a>、<a href="/guide/15-production/guardrails">护栏与内容安全</a>、<a href="/guide/15-production/cost-optimization">成本与延迟优化</a>、<a href="/guide/15-production/serving">服务化</a>、<a href="/guide/15-production/deployment">部署、监控与运维</a></li></ul><p>项目：<a href="/projects/10-enterprise-assistant">10 毕业项目：企业知识助手</a>，按生产标准交付：评估集、轨迹追踪、权限、护栏、灰度发布方案。</p><p>产出：一份《Agent 上线检查清单》，作为团队所有 Agent 上线前的统一门槛。</p><p>自检清单：</p><ul><li>[ ] 评估集覆盖正常、边界和对抗三类用例，并接入 CI</li><li>[ ] LLM-as-Judge 的评分与人工标注做过一致性校验</li><li>[ ] 线上轨迹可以抽样回流成新的评估用例</li><li>[ ] 有完整的 Prompt 注入威胁模型，工具权限遵循最小权限原则</li><li>[ ] 有成本告警、降级模型和熔断策略</li><li>[ ] 能用 <a href="/interview/engineering">工程与系统设计题</a> 中的系统设计题完整讲出一套方案</li></ul><p>完成后建议通读 <a href="/papers/">论文精读</a> 中尚未读过的论文，并用 <a href="/glossary">术语表</a> 统一团队内部用语。</p>`,45)])])}const c=a(l,[["render",n]]);export{h as __pageData,c as default};
